patch:
--- mRemoteNG/Connection/Protocol/SshDotNet/ProtocolSshDotNet.cs
@@ -266,7 +266,7 @@ private bool TryBuildAuthentication(string username, string password, Connection
                 authMethods = SshAuthenticationProvider.GetAuthenticationMethods(username, password, connectionInfo);
                 return true;
             }
-            catch (ArgumentException authEx)
+            catch (Exception authEx) when (authEx is ArgumentException or FileNotFoundException or SshException)
             {
                 SshDotNetDiagnostics.LogException("Protocol: Failed to create authentication methods", authEx);
                 State = ConnectionState.Error;
--- mRemoteNG/Connection/Protocol/SshDotNet/SshAuthenticationProvider.cs
@@ -29,22 +29,21 @@ public static AuthenticationMethod[] GetAuthenticationMethods(

             try
             {
-                // 1. Try password authentication if password is provided
-                if (!string.IsNullOrEmpty(password))
-                {
-                    SshDotNetDiagnostics.LogAuthAttempt(username, "Password");
-                    authMethods.Add(new PasswordAuthenticationMethod(username, password));
-                }
-
-                // 2. Try public key authentication if key path is configured
-                // (Property to be added in Phase 5 if needed)
+                // 1. Public-key authentication if a key file is configured (preferred, like OpenSSH).
                 var keyAuthMethod = TryCreateKeyAuthenticationFromConnectionInfo(username, connectionInfo);
                 if (keyAuthMethod != null)
                 {
                     authMethods.Add(keyAuthMethod);
                 }

-                // 3. Try keyboard-interactive (for 2FA/MFA)
+                // 2. Password authentication if a password is provided.
+                if (!string.IsNullOrEmpty(password))
+                {
+                    SshDotNetDiagnostics.LogAuthAttempt(username, "Password");
+                    authMethods.Add(new PasswordAuthenticationMethod(username, password));
+                }
+
+                // 3. Keyboard-interactive (for 2FA/MFA).
                 SshDotNetDiagnostics.LogDebug("Auth: Adding keyboard-interactive method");
                 authMethods.Add(CreateKeyboardInteractiveAuth(username, password));

@@ -208,22 +207,16 @@ private static PrivateKeyAuthenticationMethod TryCreateKeyAuthenticationFromConn
             string username,
             ConnectionInfo connectionInfo)
         {
-            // TODO: In Phase 5, if we add SSH key path property to ConnectionInfo, use it here
-            // For now, check if credential providers have SSH keys
-
-            try
+            string keyPath = connectionInfo?.SshDotNetPrivateKeyFile;
+            if (string.IsNullOrEmpty(keyPath))
             {
-                // Check for SSH key in connection properties or credential providers
-                // This is a placeholder for future implementation
-
                 SshDotNetDiagnostics.LogDebug("Auth: No SSH key path configured in connection");
                 return null;
             }
-            catch (Exception ex)
-            {
-                SshDotNetDiagnostics.LogException("Auth: Error checking for SSH key", ex);
-                return null;
-            }
+
+            // Load failures (missing file, wrong passphrase, corrupt key) are allowed to propagate so
+            // the user gets an actionable error rather than a silent fallback to password auth.
+            return CreatePrivateKeyAuth(username, keyPath, connectionInfo.SshDotNetPrivateKeyPassphrase);
         }

         #endregion
--- mRemoteNGTests/Connection/Protocol/SshDotNet/SshAuthenticationProviderTests.cs
@@ -351,6 +351,21 @@ public void GetAuthenticationMethods_ReturnsAtLeastOneMethod()
             Assert.That(authMethods.Length, Is.GreaterThan(0), "Should always return at least one authentication method");
         }

+        [Test]
+        public void GetAuthenticationMethods_ReadsKeyFile_AndSurfacesMissingFile()
+        {
+            // A connection configured to use a private key file that does not exist.
+            var connectionInfo = new mRemoteNG.Connection.ConnectionInfo
+            {
+                SshDotNetPrivateKeyFile = @"C:\does\not\exist\id_ed25519"
+            };
+
+            // Proves the connection's key property is wired into the auth flow: CreatePrivateKeyAuth
+            // is reached and surfaces the missing file rather than silently ignoring the key.
+            Assert.Throws<FileNotFoundException>(() =>
+                SshAuthenticationProvider.GetAuthenticationMethods("testuser", "password", connectionInfo));
+        }
+
         #endregion
     }
 }
